   card('قارورة', 'زجاجة', 'القارورة الكبيرة بخمسة وثلاثين؛ اشترى يوسف قارورتين لأبيه.'), card('نقدًا', 'بالمال الورقي لا بالبطاقة', 'ندفع نقدًا إذًا، قالت ماريا.'),
