   mcq('أيّ سؤال للسعر؟', ['كم المجموع؟', 'بكم؟', 'منذ متى؟'], 1, 'بكم؟ للسعر، وكم؟ للعدد والمجموع؛ هكذا تسأل ليلى وهكذا يسأل يوسف.'),
